// Baut den täglichen Statusbericht als eigenständiges HTML-Dokument im SEIL-CI.
// Struktur = Bericht-Export im Cockpit (Modul 02). Sobald SEIL eine eigene
// Reporting-Vorlage liefert, hier das Layout angleichen.
const z = $input.first().json; // erwartete Felder siehe Kennzahlen-Node
const heute = new Date().toLocaleDateString('de-DE', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' });
const kpi = (wert, label) => `<td style="padding:14px 16px;border:1px solid #37373f;border-radius:6px;background:#232328"><div style="font-size:22px;font-weight:600;color:#f4f5f6">${wert ?? '–'}</div><div style="font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#8a8f97">${label}</div></td>`;
const html = `<!doctype html><html lang="de"><meta charset="utf-8"><body style="margin:0;background:#121214;color:#c2c6cc;font-family:Inter,system-ui,sans-serif"><div style="max-width:720px;margin:0 auto;padding:32px 24px"><div style="display:flex;justify-content:space-between;border-bottom:1px solid #37373f;padding-bottom:12px"><span style="font-size:18px;font-weight:600;letter-spacing:.18em;color:#f4f5f6">SEIL</span><span style="font-size:10px;letter-spacing:.09em;text-transform:uppercase;color:#8a8f97">Statusbericht · ${heute}</span></div><table style="width:100%;border-collapse:separate;border-spacing:8px;margin:20px -8px"><tr>${kpi(z.pipelineMio ? z.pipelineMio + ' Mio €' : null, 'Pipeline')}${kpi(z.mandate, 'Aktive Mandate')}${kpi(z.antwortquote ? z.antwortquote + ' %' : null, 'Antwortquote')}${kpi(z.offeneAufgaben, 'Offene Aufgaben')}</tr></table><p style="font-size:12px;color:#8a8f97">Mandate-Tabelle und „Braucht Aufmerksamkeit“ folgen hier – Struktur wie der Bericht-Export im Cockpit.</p><p style="font-size:10px;color:#8a8f97;border-top:1px solid #37373f;padding-top:10px">Automatisch erstellt von SEIL Cockpit · n8n Workflow 07</p></div></body></html>`;
return [{ json: { ...z, betreff: `SEIL Statusbericht ${heute}`, html } }];
